static const float IAQ_B2[3] = {-0.082392283f, 0.39070716f, -0.47663178f};

// Returns 0=Good, 1=Moderate, 2=Poor
static inline int predictIAQ(const float x[10]) {
    // 1. StandardScaler
    float xs[10];
    for (int i = 0; i < 10; i++)
        xs[i] = (x[i] - IAQ_SC_MEAN[i]) / IAQ_SC_SCALE[i];

    // 2. Hidden layer 1 (10->64, ReLU)
    float h0[64];
    for (int j = 0; j < 64; j++) {
        float v = IAQ_B0[j];
        for (int i = 0; i < 10; i++) v += IAQ_W0[j][i] * xs[i];
        h0[j] = v > 0.0f ? v : 0.0f;
    }

    // 3. Hidden layer 2 (64->32, ReLU)
    float h1o[32];
    for (int j = 0; j < 32; j++) {
        float v = IAQ_B1[j];
        for (int k = 0; k < 64; k++) v += IAQ_W1[j][k] * h0[k];
        h1o[j] = v > 0.0f ? v : 0.0f;
    }

    // 4. Output layer (32->3), argmax
    int   best  = 0;
    float bestV = IAQ_B2[0];
    for (int k = 0; k < 32; k++) bestV += IAQ_W2[0][k] * h1o[k];
    for (int j = 1; j < 3; j++) {
        float v = IAQ_B2[j];
        for (int k = 0; k < 32; k++) v += IAQ_W2[j][k] * h1o[k];
        if (v > bestV) { bestV = v; best = j; }
    }
    return best;
}
